# ! [doc = " The borrowck rules for proving disjointness are applied from the \"root\" of the"] # ! [doc = " borrow forwards, iterating over \"similar\" projections in lockstep until"] # ! [doc = " we can prove overlap one way or another. Essentially, we treat `Overlap` as"] # ! [doc = " a monoid and report a conflict if the product ends up not being `Disjoint`."] # ! [doc = ""] # ! [doc = " On each step, if we didn't run out of borrow or place, we know that our elements"] # ! [doc = " have the same type, and that they only overlap if they are the identical."] # ! [doc = ""] # ! [doc = " For example, if we are comparing these:"] # ! [doc = " ```text"] # ! [doc = " BORROW:  (*x1[2].y).z.a"] # ! [doc = " ACCESS:  (*x1[i].y).w.b"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Then our steps are:"] # ! [doc = " ```text"] # ! [doc = "       x1         |   x1          -- places are the same"] # ! [doc = "       x1[2]      |   x1[i]       -- equal or disjoint (disjoint if indexes differ)"] # ! [doc = "       x1[2].y    |   x1[i].y     -- equal or disjoint"] # ! [doc = "      *x1[2].y    |  *x1[i].y     -- equal or disjoint"] # ! [doc = "     (*x1[2].y).z | (*x1[i].y).w  -- we are disjoint and don't need to check more!"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Because `zip` does potentially bad things to the iterator inside, this loop"] # ! [doc = " also handles the case where the access might be a *prefix* of the borrow, e.g."] # ! [doc = ""] # ! [doc = " ```text"] # ! [doc = " BORROW:  (*x1[2].y).z.a"] # ! [doc = " ACCESS:  x1[i].y"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Then our steps are:"] # ! [doc = " ```text"] # ! [doc = "       x1         |   x1          -- places are the same"] # ! [doc = "       x1[2]      |   x1[i]       -- equal or disjoint (disjoint if indexes differ)"] # ! [doc = "       x1[2].y    |   x1[i].y     -- equal or disjoint"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " -- here we run out of access - the borrow can access a part of it. If this"] # ! [doc = " is a full deep access, then we *know* the borrow conflicts with it. However,"] # ! [doc = " if the access is shallow, then we can proceed:"] # ! [doc = ""] # ! [doc = " ```text"] # ! [doc = "       x1[2].y    | (*x1[i].y)    -- a deref! the access can't get past this, so we"] # ! [doc = "                                     are disjoint"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Our invariant is, that at each step of the iteration:"] # ! [doc = "  - If we didn't run out of access to match, our borrow and access are comparable"] # ! [doc = "    and either equal or disjoint."] # ! [doc = "  - If we did run out of access, the borrow can access a part of it."] use split_decls_genesis :: ourprelude :: * ; use std :: cmp :: max ; use std :: iter ; use rustc_hir as hir ; use rustc_middle :: bug ; use rustc_middle :: mir :: { Body , BorrowKind , FakeBorrowKind , MutBorrowKind , Place , PlaceElem , PlaceRef , ProjectionElem , } ; use rustc_middle :: ty :: { self , TyCtxt } ; use tracing :: { debug , instrument } ; use crate :: { AccessDepth , ArtificialField , Deep , Overlap , Shallow } ; #[doc = " When checking if a place conflicts with another place, this enum is used to influence decisions"] #[doc = " where a place might be equal or disjoint with another place, such as if `a[i] == a[j]`."] #[doc = " `PlaceConflictBias::Overlap` would bias toward assuming that `i` might equal `j` and that these"] #[doc = " places overlap. `PlaceConflictBias::NoOverlap` assumes that for the purposes of the predicate"] #[doc = " being run in the calling context, the conservative choice is to assume the compared indices"] #[doc = " are disjoint (and therefore, do not overlap)."] #[derive (Copy , Clone , Debug , Eq , PartialEq)] pub enum PlaceConflictBias { Overlap , NoOverlap , } #[doc = " Helper function for checking if places conflict with a mutable borrow and deep access depth."] #[doc = " This is used to check for places conflicting outside of the borrow checking code (such as in"] #[doc = " dataflow)."] pub fn places_conflict < 'tcx > (tcx : TyCtxt < 'tcx > , body : & Body < 'tcx > , borrow_place : Place < 'tcx > , access_place : Place < 'tcx > , bias : PlaceConflictBias ,) -> bool { borrow_conflicts_with_place (tcx , body , borrow_place , BorrowKind :: Mut { kind : MutBorrowKind :: TwoPhaseBorrow } , access_place . as_ref () , AccessDepth :: Deep , bias ,) } #[doc = " Checks whether the `borrow_place` conflicts with the `access_place` given a borrow kind and"] #[doc = " access depth. The `bias` parameter is used to determine how the unknowable (comparing runtime"] #[doc = " array indices, for example) should be interpreted - this depends on what the caller wants in"] #[doc = " order to make the conservative choice and preserve soundness."] #[inline] pub (super) fn borrow_conflicts_with_place < 'tcx > (tcx : TyCtxt < 'tcx > , body : & Body < 'tcx > , borrow_place : Place < 'tcx > , borrow_kind : BorrowKind , access_place : PlaceRef < 'tcx > , access : AccessDepth , bias : PlaceConflictBias ,) -> bool { let borrow_local = borrow_place . local ; let access_local = access_place . local ; if borrow_local != access_local { return false ; } if borrow_place . projection . is_empty () && access_place . projection . is_empty () { return true ; } place_components_conflict (tcx , body , borrow_place , borrow_kind , access_place , access , bias) } #[instrument (level = "debug" , skip (tcx , body))] fn place_components_conflict < 'tcx > (tcx : TyCtxt < 'tcx > , body : & Body < 'tcx > , borrow_place : Place < 'tcx > , borrow_kind : BorrowKind , access_place : PlaceRef < 'tcx > , access : AccessDepth , bias : PlaceConflictBias ,) -> bool { let borrow_local = borrow_place . local ; let access_local = access_place . local ; assert_eq ! (borrow_local , access_local) ; for ((borrow_place , borrow_c) , & access_c) in iter :: zip (borrow_place . iter_projections () , access_place . projection) { debug ! (? borrow_c , ? access_c) ; match place_projection_conflict (tcx , body , borrow_place , borrow_c , access_c , bias) { Overlap :: Arbitrary => { debug ! ("arbitrary -> conflict") ; return true ; } Overlap :: EqualOrDisjoint => { } Overlap :: Disjoint => { debug ! ("disjoint") ; return false ; } } } if borrow_place . projection . len () > access_place . projection . len () { for (base , elem) in borrow_place . iter_projections () . skip (access_place . projection . len ()) { let base_ty = base . ty (body , tcx) . ty ; match (elem , base_ty . kind () , access) { (_ , _ , Shallow (Some (ArtificialField :: ArrayLength))) | (_ , _ , Shallow (Some (ArtificialField :: FakeBorrow))) => { debug ! ("borrow_conflicts_with_place: implicit field") ; return false ; } (ProjectionElem :: Deref , _ , Shallow (None)) => { debug ! ("borrow_conflicts_with_place: shallow access behind ptr") ; return false ; } (ProjectionElem :: Deref , ty :: Ref (_ , _ , hir :: Mutability :: Not) , _) => { bug ! ("Tracking borrow behind shared reference.") ; } (ProjectionElem :: Deref , ty :: Ref (_ , _ , hir :: Mutability :: Mut) , AccessDepth :: Drop) => { debug ! ("borrow_conflicts_with_place: drop access behind ptr") ; return false ; } (ProjectionElem :: Field { .. } , ty :: Adt (def , _) , AccessDepth :: Drop) => { if def . has_dtor (tcx) { return true ; } } (ProjectionElem :: Deref , _ , Deep) | (ProjectionElem :: Deref , _ , AccessDepth :: Drop) | (ProjectionElem :: Field { .. } , _ , _) | (ProjectionElem :: Index { .. } , _ , _) | (ProjectionElem :: ConstantIndex { .. } , _ , _) | (ProjectionElem :: Subslice { .. } , _ , _) | (ProjectionElem :: OpaqueCast { .. } , _ , _) | (ProjectionElem :: Subtype (_) , _ , _) | (ProjectionElem :: Downcast { .. } , _ , _) | (ProjectionElem :: UnwrapUnsafeBinder (_) , _ , _) => { } } } } if borrow_kind == BorrowKind :: Fake (FakeBorrowKind :: Shallow) && borrow_place . projection . len () < access_place . projection . len () { debug ! ("borrow_conflicts_with_place: shallow borrow") ; false } else { debug ! ("borrow_conflicts_with_place: full borrow, CONFLICT") ; true } } fn place_projection_conflict < 'tcx > (tcx : TyCtxt < 'tcx > , body : & Body < 'tcx > , pi1 : PlaceRef < 'tcx > , pi1_elem : PlaceElem < 'tcx > , pi2_elem : PlaceElem < 'tcx > , bias : PlaceConflictBias ,) -> Overlap { match (pi1_elem , pi2_elem) { (ProjectionElem :: Deref , ProjectionElem :: Deref) => { debug ! ("place_element_conflict: DISJOINT-OR-EQ-DEREF") ; Overlap :: EqualOrDisjoint } (ProjectionElem :: OpaqueCast (_) , ProjectionElem :: OpaqueCast (_)) => { debug ! ("place_element_conflict: DISJOINT-OR-EQ-OPAQUE") ; Overlap :: EqualOrDisjoint } (ProjectionElem :: Field (f1 , _) , ProjectionElem :: Field (f2 , _)) => { if f1 == f2 { debug ! ("place_element_conflict: DISJOINT-OR-EQ-FIELD") ; Overlap :: EqualOrDisjoint } else { let ty = pi1 . ty (body , tcx) . ty ; if ty . is_union () { debug ! ("place_element_conflict: STUCK-UNION") ; Overlap :: Arbitrary } else { debug ! ("place_element_conflict: DISJOINT-FIELD") ; Overlap :: Disjoint } } } (ProjectionElem :: Downcast (_ , v1) , ProjectionElem :: Downcast (_ , v2)) => { if v1 == v2 { debug ! ("place_element_conflict: DISJOINT-OR-EQ-FIELD") ; Overlap :: EqualOrDisjoint } else { debug ! ("place_element_conflict: DISJOINT-FIELD") ; Overlap :: Disjoint } } (ProjectionElem :: Index (..) , ProjectionElem :: Index (..) | ProjectionElem :: ConstantIndex { .. } | ProjectionElem :: Subslice { .. } ,) | (ProjectionElem :: ConstantIndex { .. } | ProjectionElem :: Subslice { .. } , ProjectionElem :: Index (..) ,) => { match bias { PlaceConflictBias :: Overlap => { debug ! ("place_element_conflict: DISJOINT-OR-EQ-ARRAY-INDEX") ; Overlap :: EqualOrDisjoint } PlaceConflictBias :: NoOverlap => { debug ! ("place_element_conflict: DISJOINT-ARRAY-INDEX") ; Overlap :: Disjoint } } } (ProjectionElem :: ConstantIndex { offset : o1 , min_length : _ , from_end : false } , ProjectionElem :: ConstantIndex { offset : o2 , min_length : _ , from_end : false } ,) | (ProjectionElem :: ConstantIndex { offset : o1 , min_length : _ , from_end : true } , ProjectionElem :: ConstantIndex { offset : o2 , min_length : _ , from_end : true } ,) => { if o1 == o2 { debug ! ("place_element_conflict: DISJOINT-OR-EQ-ARRAY-CONSTANT-INDEX") ; Overlap :: EqualOrDisjoint } else { debug ! ("place_element_conflict: DISJOINT-ARRAY-CONSTANT-INDEX") ; Overlap :: Disjoint } } (ProjectionElem :: ConstantIndex { offset : offset_from_begin , min_length : min_length1 , from_end : false , } , ProjectionElem :: ConstantIndex { offset : offset_from_end , min_length : min_length2 , from_end : true , } ,) | (ProjectionElem :: ConstantIndex { offset : offset_from_end , min_length : min_length1 , from_end : true , } , ProjectionElem :: ConstantIndex { offset : offset_from_begin , min_length : min_length2 , from_end : false , } ,) => { let min_length = max (min_length1 , min_length2) ; if offset_from_begin >= min_length - offset_from_end { debug ! ("place_element_conflict: DISJOINT-OR-EQ-ARRAY-CONSTANT-INDEX-FE") ; Overlap :: EqualOrDisjoint } else { debug ! ("place_element_conflict: DISJOINT-ARRAY-CONSTANT-INDEX-FE") ; Overlap :: Disjoint } } (ProjectionElem :: ConstantIndex { offset , min_length : _ , from_end : false } , ProjectionElem :: Subslice { from , to , from_end : false } ,) | (ProjectionElem :: Subslice { from , to , from_end : false } , ProjectionElem :: ConstantIndex { offset , min_length : _ , from_end : false } ,) => { if (from .. to) . contains (& offset) { debug ! ("place_element_conflict: DISJOINT-OR-EQ-ARRAY-CONSTANT-INDEX-SUBSLICE") ; Overlap :: EqualOrDisjoint } else { debug ! ("place_element_conflict: DISJOINT-ARRAY-CONSTANT-INDEX-SUBSLICE") ; Overlap :: Disjoint } } (ProjectionElem :: ConstantIndex { offset , min_length : _ , from_end : false } , ProjectionElem :: Subslice { from , .. } ,) | (ProjectionElem :: Subslice { from , .. } , ProjectionElem :: ConstantIndex { offset , min_length : _ , from_end : false } ,) => { if offset >= from { debug ! ("place_element_conflict: DISJOINT-OR-EQ-SLICE-CONSTANT-INDEX-SUBSLICE") ; Overlap :: EqualOrDisjoint } else { debug ! ("place_element_conflict: DISJOINT-SLICE-CONSTANT-INDEX-SUBSLICE") ; Overlap :: Disjoint } } (ProjectionElem :: ConstantIndex { offset , min_length : _ , from_end : true } , ProjectionElem :: Subslice { to , from_end : true , .. } ,) | (ProjectionElem :: Subslice { to , from_end : true , .. } , ProjectionElem :: ConstantIndex { offset , min_length : _ , from_end : true } ,) => { if offset > to { debug ! ("place_element_conflict: \
                       DISJOINT-OR-EQ-SLICE-CONSTANT-INDEX-SUBSLICE-FE") ; Overlap :: EqualOrDisjoint } else { debug ! ("place_element_conflict: DISJOINT-SLICE-CONSTANT-INDEX-SUBSLICE-FE") ; Overlap :: Disjoint } } (ProjectionElem :: Subslice { from : f1 , to : t1 , from_end : false } , ProjectionElem :: Subslice { from : f2 , to : t2 , from_end : false } ,) => { if f2 >= t1 || f1 >= t2 { debug ! ("place_element_conflict: DISJOINT-ARRAY-SUBSLICES") ; Overlap :: Disjoint } else { debug ! ("place_element_conflict: DISJOINT-OR-EQ-ARRAY-SUBSLICES") ; Overlap :: EqualOrDisjoint } } (ProjectionElem :: Subslice { .. } , ProjectionElem :: Subslice { .. }) => { debug ! ("place_element_conflict: DISJOINT-OR-EQ-SLICE-SUBSLICES") ; Overlap :: EqualOrDisjoint } (ProjectionElem :: Deref | ProjectionElem :: Field (..) | ProjectionElem :: Index (..) | ProjectionElem :: ConstantIndex { .. } | ProjectionElem :: Subtype (_) | ProjectionElem :: OpaqueCast { .. } | ProjectionElem :: Subslice { .. } | ProjectionElem :: Downcast (..) , _ ,) => bug ! ("mismatched projections in place_element_conflict: {:?} and {:?}" , pi1_elem , pi2_elem) , (ProjectionElem :: UnwrapUnsafeBinder (_) , _) => { todo ! () } } }